/* Stranded II service worker (generated by tools/build.mjs — edit src/sw.template.js).
 * Everything the game needs is cached at install, so it plays offline. Each build has its own
 * cache name; a new build installs in the background and takes over on the next launch. */
const CACHE = 'stranded-c903f453ae7c';
const PRECACHE = ["./","assets/mars/color.jpg","assets/mars/height.bin","assets/mars/map.jpg","assets/models/astronaut.glb","assets/models/farm_plot.glb","assets/models/hab.glb","assets/models/hermes.glb","assets/models/mav.glb","assets/models/rover.glb","assets/models/solar_panel.glb","assets/models/uplink_dish.glb","game.css","game.js","manifest.webmanifest","terrain-worker.js"];
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('stranded-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || !req.url.startsWith(self.location.origin)) return;
  // the page itself: network first, so a new build is noticed as soon as there is a connection
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).then((res) => {
      if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put('./', copy)); }
      return res;
    }).catch(() => caches.match('./')));
    return;
  }
  // everything else: this build's cache first (file names are stable, the cache name is not)
  e.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return res;
  })));
});
